package syn; import net.minecraft.world.level.block.Block; import net.minecraft.world.level.block.state.BlockBehaviour; import net.minecraftforge.registries.*; public class Reg { public static final DeferredRegister<Block> BLOCKS = DeferredRegister.create(ForgeRegistries.BLOCKS, "synmod"); static { for (Color c : Color.values()) { BLOCKS.register("stick_" + c.getName(), () -> new SynBlock(BlockBehaviour.Properties.of())); BLOCKS.register("creative_stick_" + c.getName(), () -> new SynBlock(BlockBehaviour.Properties.of())); } BLOCKS.register("weird_ext", () -> new WeirdExtBlock(BlockBehaviour.Properties.of())); BLOCKS.register("weird_arr", () -> new WeirdArrBlock(BlockBehaviour.Properties.of())); BLOCKS.register("triple", () -> new TripleBlock(BlockBehaviour.Properties.of())); } }
